import React from 'react';

function Skills() {
  const skills = {
    frontend: [
      'HTML5', 'CSS3', 'JavaScript (ES6+)', 'React.js', 'Redux', 'Next.js',
      'TypeScript', 'Tailwind CSS', 'Bootstrap', 'Sass/Less', 'Responsive Design'
    ],
    backend: [
      'Node.js', 'Express.js', 'Python', 'Django', 'Flask', 'RESTful APIs', 'GraphQL'
    ],
    databases: [
      'MongoDB', 'PostgreSQL', 'MySQL', 'Firebase'
    ],
    tools: [
      'Git', 'GitHub', 'VS Code', 'Webpack', 'Babel', 'Figma', 'Jira', 'Agile Methodologies'
    ],
    uiux: [
      'UI/UX Principles', 'Wireframing', 'Prototyping', 'User Research', 'Usability Testing'
    ]
  };

  return (
    <section id="skills" className="py-20 bg-gray-900 text-white">
      <div className="container mx-auto px-4">
        <h2 className="text-4xl font-bold text-center mb-12 text-blue-400">My Skills</h2>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
          {Object.entries(skills).map(([category, skillList]) => (
            <div key={category} className="bg-gray-800 p-6 rounded-lg shadow-lg transform hover:scale-105 transition duration-300">
              <h3 className="text-2xl font-semibold mb-4 capitalize text-blue-300">{category.replace(/([A-Z])/g, ' $1')}</h3>
              <ul className="space-y-2">
                {skillList.map((skill, index) => (
                  <li key={index} className="flex items-center text-lg">
                    <svg className="w-5 h-5 text-blue-400 mr-2" fill="currentColor" viewBox="0 0 20 20" xmlns="http://www.w3.org/2000/svg">
                      <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd"></path>
                    </svg>
                    {skill}
                  </li>
                ))}
              </ul>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}

export default Skills;
